from datetime import date, datetime, timedelta
from unittest.mock import patch

import pytest

from dispatch.case import scheduled
from dispatch.case.enums import CaseStatus


def _freeze_today(day: date):
    class FrozenDate(date):
        @classmethod
        def today(cls):
            return day

    return patch.object(scheduled, "date", FrozenDate)


# 2025-08-17 is a Sunday, 2025-08-18 a Monday
@pytest.mark.parametrize("offset", range(7))
def test_is_reminder_day_only_on_monday(offset):
    day = date(2025, 8, 17) + timedelta(days=offset)
    with _freeze_today(day):
        assert scheduled._is_reminder_day() == (day.strftime("%A") == "Monday")


@pytest.mark.parametrize(
    "today,expected_calls",
    [(date(2025, 8, 17), 0), (date(2025, 8, 18), 1)],
)
def test_case_stable_reminder_sends_on_monday_not_sunday(today, expected_calls):
    class FakeCase:
        stable_at = datetime.utcnow() - timedelta(days=30)

    with _freeze_today(today), patch.object(
        scheduled, "get_all_by_status", return_value=[FakeCase()]
    ) as get_cases, patch.object(scheduled, "send_case_close_reminder") as send:
        scheduled.case_stable_reminder.__wrapped__ if False else None
        # bypass the per-project scheduler decorators
        func = scheduled.case_stable_reminder
        while hasattr(func, "__wrapped__"):
            func = func.__wrapped__
        func(db_session=None, project=type("P", (), {"id": 1})())

    assert get_cases.call_args.kwargs["statuses"] == [CaseStatus.stable]
    assert send.call_count == expected_calls
EOF
sed -i '/__wrapped__ if False/d' tests/case/test_case_scheduled.py
python -m pytest tests/case/test_case_scheduled.py -q 2>&1 | tail -8; git stash -q -- src; python -m pytest tests/case/test_case_scheduled.py -q 2>&1 | tail -5; git stash pop -q; git status --short

